<script>const p=document.getElementById('password'),t=document.getElementById('password-toggle');t.addEventListener('click',()=>{const show=p.type==='password';p.type=show?'text':'password';t.setAttribute('aria-pressed',show);t.setAttribute('aria-label',show?'Hide password':'Show password');t.title=show?'Hide password':'Show password'});const b=document.querySelector('.brand'),l=document.getElementById('l3d');b.onpointermove=e=>{const r=b.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;l.classList.add('m');l.style.transform=`rotateX(${-y*40}deg) rotateY(${x*60}deg)`};b.onpointerleave=()=>{l.classList.remove('m');l.style.transform=''}</script></body></html>
